# greet

A tiny Node.js command-line tool that greets people.
#!/usr/bin/env node

const args = process.argv.slice(2);

if (args.includes('--version')) {
  console.log(require('../package.json').version);
  process.exit(0);
}

const name = args[0] || 'world';

console.log(`Hello, ${name}!`);
{
  "name": "greet",
  "version": "0.1.0",
  "private": true,
  "scripts": {
    "test": "node --test"
  }
}
const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const path = require('node:path');
const test = require('node:test');

const command = path.join(__dirname, '..', 'bin', 'greet.js');

test('greets a named person', () => {
  const result = spawnSync(process.execPath, [command, 'Mike'], { encoding: 'utf8' });

  assert.equal(result.status, 0);
  assert.equal(result.stdout, 'Hello, Mike!\n');
  assert.equal(result.stderr, '');
});

test('greets the world when no name is supplied', () => {
  const result = spawnSync(process.execPath, [command], { encoding: 'utf8' });

  assert.equal(result.status, 0);
  assert.equal(result.stdout, 'Hello, world!\n');
  assert.equal(result.stderr, '');
});

test('prints the version', () => {
  const result = spawnSync(process.execPath, [command, '--version'], { encoding: 'utf8' });

  assert.equal(result.status, 0);
  assert.equal(result.stdout, '0.1.0\n');
  assert.equal(result.stderr, '');
});

test('version takes precedence over a name', () => {
  const result = spawnSync(process.execPath, [command, 'Mike', '--version'], { encoding: 'utf8' });

  assert.equal(result.status, 0);
  assert.equal(result.stdout, '0.1.0\n');
  assert.equal(result.stderr, '');
});
